"""Printed 286–288: complete differential-equation opening and examples 1–3."""
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_native_geometry import geometry,path
OBJECTIVES=[('10.1 Introduction',['Define ordinary differential equation (DE), order of a DE, degree of a DE, solution of a DE — general solution and particular solution.']),('10.2 Formation of differential equations',['Demonstrate the concept of formation of a differential equation.']),('10.3 Solution of differential equation',['Solve first-order, first-degree equations with separable variables, homogeneous equations and equations reducible to homogeneous form.','Solve real-life problems related to differential equations.']),('10.4 Orthogonal Trajectories',['Find orthogonal trajectories (rectangular coordinates) of the given family of curves.','Use MAPLE graphic commands to view graphs of a given family of curves and its orthogonal trajectories.'])]
INTRO=[heading('Introduction'),paragraph('The laws of the universe are written in the language of mathematics. Algebra is sufficient to solve many static problems, but the most interesting natural phenomena involve change and are described only by equations that relate rates at which quantities change.'),paragraph('Suppose the solution of problems concerning motion of objects, flow of charged particles, heat transport, etc., often involves relations of the form:'),eq(r'\frac{dx}{dt}=f(x,t)\quad\mathrm{or}\quad\frac{dq}{dt}=g(q,t)'),paragraph('In the first equation x might represent distance. Its rate of change with respect to time is speed. In the second, q might be charge and dq/dt the rate of flow of charge, current. These are examples of different equations, so called because they involve derivatives of various quantities. Such equations arise in situations in which change is occurring.'),paragraph('In engineering, differential equations commonly model dynamic systems, systems changing with time. Examples include electronic circuits with time-dependent currents/voltages and chemical production lines where pressure, tank levels, flow rates, etc., vary with time. There is a wide variety of differential equations and consequently solution techniques.'),note('The source phrase “different equations” means differential equations. If x is signed position, dx/dt is velocity and speed is |dx/dt|; if x is cumulative distance travelled, its derivative is speed. The functions f,g specify the particular model rather than being arbitrary known numerical rates.')]
def family_graph():
 def pt(x,y):return(235+39*x,225-39*y)
 paths=[path([pt(-4,0),pt(4.8,0)]),path([pt(0,-3),pt(0,4.7)])];labels=[(427,230,'x'),(233,31,'y'),(213,247,'O')]
 for a in [0,1,2,3]:
  x0=max(-4,-3-a);x1=min(4,4.4-a);paths.append(path([pt(x0,x0+a),pt(x1,x1+a)],stroke='#0369a1' if a==1 else '#64748b'));xx,yy=pt(x1,x1+a);labels.append((xx+5,yy+5,'A='+str(a)))
 for v in [-3,-2,-1,1,2,3]:
  xx,yy=pt(v,0);paths.append(path([(xx,yy-4),(xx,yy+4)]));labels.append((xx-4,yy+23,str(v)))
  xx,yy=pt(0,v);paths.append(path([(xx-4,yy),(xx+4,yy)]));labels.append((xx-25,yy+5,str(v)))
 x,y=pt(0,1);labels.extend([(x+8,y+20,'(0,1)'),(365,122,'Particular line'),(320,145,'y=x+1')])
 return geometry('Figure 10.1','Figure 10.1 — general solution family y=x+A for A=0,1,2,3 and the particular line through (0,1)',paths,labels,points=[{'x':x,'y':y}],size=(495,375))
PAGES=[page('147_page_2.jpg',286,INTRO+[heading('10.1 Ordinary Differential Equations'),paragraph('A differential equation is an equation that involves the derivatives of an unknown function (dependent variable) of one or more variables (independent variables). If the unknown function depends on only one variable, the derivative is an ordinary derivative and the equation is called an ordinary differential equation. If the unknown depends on more than one variable, the derivative is a partial derivative and the equation is called a partial differential equation.')]),
page('148_page_1.jpg',287,[paragraph('The following are examples of ordinary differential equations with their corresponding unknown functions:'),eq(r'\frac{dy}{dx}=xy,\quad y(x)=?','i'),eq(r'\frac{dy}{dx}=x+y,\quad y(x)=?','ii'),eq(r'\frac{dy}{dx}=\frac{x+y}{x-y},\quad y(x)=?','iii'),eq(r'\frac{d^2y}{dx^2}+2x\frac{dy}{dx}+y=3,\quad y(x)=?','iv'),eq(r'\left(\frac{d^3y}{dx^3}\right)^2-\frac{d^2y}{dx^2}+x^2\frac{dy}{dx}+y=3,\quad y(x)=?','v'),heading('(a) Order of a differential equation'),paragraph('The order is the order of the highest-order derivative occurring in the equation, e.g.:'),eq(r'\frac{dy}{dx}=xy\quad\mathrm{is\ first\ order}'),eq(r'\frac{d^2y}{dx^2}+(x^2+2x)y=7\quad\mathrm{is\ second\ order}'),heading('(b) Degree of a differential equation'),paragraph('The degree is the power of the highest-order derivative occurring in the equation.'),eq(r'\frac{d^3y}{dx^3}+\left(\frac{d^2y}{dx^2}\right)^2-8\frac{dy}{dx}+2y=8\quad\mathrm{has\ degree}\ 1'),heading('Example 1'),paragraph('Determine order and degree of these ordinary differential equations:'),eq(r'\mathrm{(a)}\ \frac{dy}{dx}=\frac{x+y}{x-y}'),eq(r'\mathrm{(b)}\ \frac{d^2y}{dx^2}+2x\frac{dy}{dx}+y=3'),eq(r'\mathrm{(c)}\ \left(\frac{d^3y}{dx^3}\right)^2-\frac{d^2y}{dx^2}+x^2\frac{dy}{dx}+y=3'),heading('Solution'),paragraph('Equation (a) has order 1 and degree 1, since the highest derivative is order 1 and its exponent is 1. Equation (b) has order 2 and degree 1, while equation (c) has order 3 and degree 2.'),heading('(c) Solution of a differential equation'),paragraph('A solution of a single-variable equation is a number satisfying it. Differential-equation solutions are functions rather than numbers. Variables appearing in equations are called unknowns; exactly, the only dependent variable is referred to as the unknown. For illustration, a solution of dy/dx=1 is an expression of y in terms of independent x. A solution of an ordinary differential is any function y=f(x) or f(x,y), which when substituted reduces the equation to an identity, satisfying it.'),note('The degree convention requires the equation to be polynomial in its derivatives after permissible removal of derivative denominators/radicals; a transcendental derivative expression such as sin(y′) does not have a degree by this definition. The order and degree are different: the lower-order squared term does not change the example’s degree 1 when y‴ is highest and linear. In Example 1(a), x≠y is part of the original domain; clearing that denominator must retain the restriction. A solution is a sufficiently differentiable function on an interval; an implicit relation F(x,y)=0 must define such a solution branch, not just an arbitrary two-variable expression.')]),
page('148_page_2.jpg',288,[heading('Example 2'),paragraph('Show that y=x+A is a solution of first-order differential equation dy/dx=1.'),heading('Solution'),paragraph('Use the function and its derivative in the equation:'),eq(r'\frac{dy}{dx}=1\quad\Rightarrow\quad1=1,\quad\mathrm{left\ side=right\ side}'),paragraph('This shows y=x+A is a solution of the ordinary differential equation dy/dx=1.'),heading('(d) General and particular solution'),paragraph('A solution depending on a single arbitrary constant is called the general solution of a first-order differential equation. Giving a particular value to the arbitrary constant obtains a particular solution.'),heading('Do You Know?'),paragraph('The particular solution is also known as specific solution or exact solution or actual solution.'),heading('Graphically'),paragraph('The general solution of a first-order equation represents a family of curves for any choice of the arbitrary constant. A particular solution is a curve chosen from that family for a particular constant.'),heading('Example 3'),paragraph('Graphically show y=x+A is a general solution of dy/dx=1. Find a particular solution when x=0,y=1.'),heading('Solution'),paragraph('The general solution y=x+A represents a family of parallel straight lines for different constant values A=0,1,2,... . The line passing through P(0,1) is found by substituting x=0,y=1:'),eq(r'y=x+A\quad\Rightarrow\quad1=0+A\quad\Rightarrow\quad A=1'),paragraph('Use A=1 to obtain the particular line y=x+1.'),family_graph(),heading('Note'),paragraph('If a differential-equation solution is subject to conditions on the unknown function and its derivatives at one value of the independent variable, these are initial conditions and the related differential equation is called an initial value problem (IVP). Thus Example 3 is:'),eq(r'\frac{dy}{dx}=1,\quad y(0)=1,\quad\mathrm{IVP}'),note('A is constant when differentiating. Every differentiable solution of y′=1 on a connected interval is x+A, not merely a trial family: the derivative of y−x is zero. The displayed A=0,1,2,3 lines are sample members; A may be any real constant. “Particular” refers to a chosen family member, while “exact” describes precision and does not mean the same thing generally. For many first-order equations a one-constant family describes general local solutions, but singular solutions and interval/domain conditions may also need treatment.')])]
PAGES[0]['objectives']=OBJECTIVES
for v in PAGES:v.update(title='DIFFERENTIAL EQUATIONS',visualStatus='Complete source definitions, degree/order equations and native solution-family graph',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':(v['page']+9)//2,'side':'left' if v['page']%2 else 'right','reason':'Every derivative order, exponent, arbitrary constant and IVP condition visually checked'})
EXAMPLES=[]
for n,q,steps,ans,pg in [
('1','Find order and degree: (a) y′=(x+y)/(x−y); (b) y″+2xy′+y=3; (c) (y‴)²−y″+x²y′+y=3.',['Order counts the highest derivative; degree is its power when the equation is polynomial in derivatives.','(a) The highest derivative is y′, so the order is 1.','It appears linearly: degree 1. Clearing (x−y) gives (x−y)y′−x−y=0 while retaining x≠y.','(b) The highest derivative is y″ and its exponent is 1, hence order 2, degree 1.','(c) The highest derivative is y‴, squared. Hence order 3 and degree 2.','The powers x² and lower-order derivatives do not determine degree; it concerns the highest-order derivative only.'],'(a) order 1, degree 1; (b) order 2, degree 1; (c) order 3, degree 2.',287),
('2','Show y=x+A solves dy/dx=1.',['Treat A as a fixed arbitrary constant.','Differentiate y=x+A: dy/dx=1+0=1.','Substitute this derivative into the differential equation dy/dx=1.','The two sides are equal identically for every real x and every real constant A.','Thus each function y=x+A is a solution. On any connected interval, d(y−x)/dx=0 implies y−x=A.','This also shows the family contains all differentiable solutions there; it is the general solution.'],'y=x+A solves y′=1 for every constant A.',288),
('3','Graph y=x+A as the general solution of y′=1 and find the solution with y(0)=1.',['Each member y=x+A has slope 1 and y-intercept A.','Plot A=0,1,2,3 to obtain four parallel lines; these illustrate the full real-constant family.','The initial condition requires the chosen line to pass through (0,1).','Substitute in y=x+A: 1=0+A, giving A=1.','Hence the particular solution is y=x+1, the highlighted line through (0,1).','Its derivative is 1 and its value at x=0 is 1, so it satisfies both the differential equation and initial condition.'],'General y=x+A; IVP solution y=x+1.',288)]:
 e={'num':n,'title':'Differential Equation Definitions','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':pg,'jpg':f'{(pg+9)//2:03d}_page_{1 if pg%2 else 2}.jpg','verification':'Complete source derivative orders, solution and initial value checked'}]}
 if n=='3':e['sourceQuestionBlocks']=[family_graph()]
 EXAMPLES.append(e)
